// recordsTop is the number of efforts listed per distance.
const recordsTop = 3

type recordGroup struct {
	ID, Label string
}

var recordGroups = []recordGroup{{analysis.GroupBike, "🚴 Rad"}, {analysis.GroupRun, "🏃 Laufen"}, {analysis.GroupHike, "🥾 Wandern"}}

// recordEntry is one place in a best-effort list.
type recordEntry struct {
	Place      int
	Medal      string
	Raw        float64
	Value      string
	Detail     string
	ActivityID int64
	Title      string
	Date       string
}

type recordList struct {
	Name    string
	Entries []recordEntry
}

type recordsData struct {
	Groups    []recordGroup
	Group     string
	Years     []int
	Year      int // 0 = all years
	Distances []recordList
	Climbs    []recordEntry
	Power     []powerRow
	HasPower  bool
	Chart     template.JS
}

// powerRow compares the best power of the selected period with all time.
type powerRow struct {
	Label   string
	Period  *recordEntry
	AllTime *recordEntry
}

type powerChart struct {
	Labels  []string   `json:"labels"`
	Period  []*float64 `json:"period"`
	AllTime []*float64 `json:"allTime"`
	// PeriodLabel names the selected period ("2026"); empty for all years.
	PeriodLabel string `json:"periodLabel"`
}

func (s *server) records(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	q := r.URL.Query()
	d := recordsData{Groups: recordGroups, Group: analysis.GroupBike}
	for _, g := range recordGroups {
		if q.Get("grp") == g.ID {
			d.Group = g.ID
		}
	}
	var err error
	if d.Years, err = s.Store.Years(ctx); err != nil {
		s.serverError(w, "list years", err)
		return
	}
	if y, err := strconv.Atoi(q.Get("year")); err == nil && y >= 1990 && y <= 2100 {
		d.Year = y
	}
	var from, to time.Time
	if d.Year != 0 {
		from, to = yearStart(d.Year), yearStart(d.Year+1)
	}
	entries := func(kind string, key, limit int, from, to time.Time) ([]recordEntry, error) {
		list, err := s.Store.TopEfforts(ctx, d.Group, kind, key, from, to, limit)
		if err != nil {
			return nil, err
		}
		out := make([]recordEntry, len(list))
		for i, e := range list {
			out[i] = newRecordEntry(i+1, e)
		}
		return out, nil
	}

	distances := analysis.BikeDistances
	if d.Group == analysis.GroupRun {
		distances = analysis.RunDistances
	} else if d.Group == analysis.GroupHike {
		distances = nil
	}
	for _, m := range distances {
		e, err := entries(store.EffortDistance, m, recordsTop, from, to)
		if err != nil {
			s.serverError(w, "top efforts", err)
			return
		}
		if len(e) > 0 {
			d.Distances = append(d.Distances, recordList{Name: analysis.DistanceLabel(m), Entries: e})
		}
	}
	if d.Climbs, err = entries(store.EffortClimb, 0, 5, from, to); err != nil {
		s.serverError(w, "top climbs", err)
		return
	}
	if d.Group == analysis.GroupBike {
		chart := powerChart{}
		if d.Year != 0 {
			chart.PeriodLabel = strconv.Itoa(d.Year)
		}
		for _, sec := range analysis.PowerDurations {
			row := powerRow{Label: analysis.DurationLabel(sec)}
			all, err := entries(store.EffortPower, sec, 1, time.Time{}, time.Time{})
			if err != nil {
				s.serverError(w, "power curve", err)
				return
			}
			if len(all) == 0 {
				continue
			}
			row.AllTime = &all[0]
			chart.Labels = append(chart.Labels, row.Label)
			chart.AllTime = append(chart.AllTime, wattsOf(all[0]))
			if d.Year != 0 {
				period, err := entries(store.EffortPower, sec, 1, from, to)
				if err != nil {
					s.serverError(w, "power curve", err)
					return
				}
				if len(period) > 0 {
					row.Period = &period[0]
					chart.Period = append(chart.Period, wattsOf(period[0]))
				} else {
					chart.Period = append(chart.Period, nil)
				}
			}
			d.Power = append(d.Power, row)
		}
		d.HasPower = len(d.Power) > 0
		b, _ := json.Marshal(chart)
		d.Chart = template.JS(b)
	}
	s.render(w, r, "records.html", "stats", d)
}

func newRecordEntry(place int, e store.EffortRecord) recordEntry {
	a := store.Activity{StartTime: e.StartTime, TZOffsetS: e.TZOffsetS}
	title := e.Name
	if title == "" {
		title = sport.Label(e.Sport, e.SubSport)
	}
	v, detail := effortValue(e.Effort)
	return recordEntry{Place: place, Medal: medal(place), Raw: e.Value, Value: v, Detail: detail, ActivityID: e.ActivityID,
		Title: title, Date: a.LocalStart().Format("02.01.2006")}
}

// wattsOf returns the watts of an entry for the chart.
func wattsOf(e recordEntry) *float64 {
	w := e.Raw
	return &w
}
